/**
 * The `renderer` half of the Inflow `@form` protocol.
 *
 * Until now a plugin's answer on `@intro` / `@settings` / `<action>.@form` was
 * one thing: a JSON Schema plus a JSON Forms UI schema, drawn by
 * `@inflowenger/plugin-form-builder`. That covers the overwhelming majority of
 * dialogs and stays the default — a declarative form is inspectable, diffable,
 * generated by `formkit`, and carries no code at all, which is the strongest
 * security property a plugin UI can have.
 *
 * Some dialogs are not forms. A query builder, a table of rows to pick from, a
 * diff view, a canvas, a connection map — expressing those as JSON Schema means
 * inventing a widget vocabulary for each one and shipping it in the host, which
 * puts the host on the critical path of every plugin's UI. The alternative is to
 * let the plugin ship *code*, which it must then be prevented from abusing.
 *
 * So a form document may now name the renderer it wants:
 *
 * ```jsonc
 * {
 *   "jsonschema": "{...}",          // still the data contract, whichever renderer draws it
 *   "jsonui":     "{...}",          // only the jsonforms renderer reads this
 *   "renderer":   "remote",         // or the object form below
 * }
 * ```
 *
 * Absent — as in every form that exists today — it reads as `"jsonforms"`, so
 * nothing already deployed changes behaviour. That is the whole compatibility
 * story: one optional key, defaulted.
 *
 * @see RendererSpec for the object form
 * @see ../README.md for the threat model behind the two code renderers
 */

/**
 * Which engine draws the form.
 *
 * - `jsonforms` — the default. JSON Schema + UI schema, no code. What every
 *   existing plugin serves, and what a plugin should keep serving unless it
 *   genuinely cannot express its dialog declaratively.
 * - `remote` — the plugin ships JavaScript, which runs in a **Web Worker** and
 *   builds its tree through Remote DOM. The worker has no DOM, no `document`,
 *   no cookies, no storage and no same-origin network; the nodes the user sees
 *   are *host* nodes, created by the host from an allow-list, which is why the
 *   host's CSS and theme apply to them with no bridging at all.
 * - `iframe` — the plugin ships JavaScript, which runs in a null-origin
 *   sandboxed `<iframe>` with a real DOM of its own. More capable (a real
 *   document, canvas, third-party widgets) and more isolated from the host's
 *   *rendering* — which is also its cost: the host's stylesheet does not reach
 *   it, so the theme has to be injected and the height synchronised, and the
 *   guest's popovers cannot escape the frame.
 *
 * Unknown values fall back to `jsonforms`, so a host that predates a renderer a
 * plugin asks for degrades to the declarative form rather than to nothing.
 */
export type RendererType = 'jsonforms' | 'remote' | 'iframe'

/** Informational: what the guest bundle was built from. Never changes how the
 *  host behaves — it is reported in errors and devtools so a failing guest is
 *  attributable. */
export type GuestFramework = 'vanilla' | 'vue' | 'react' | 'preact' | 'svelte' | string

/**
 * The object form of `renderer`, for everything beyond naming the engine.
 *
 * Exactly one of `module` / `code` must be present for a code renderer. A
 * `module` URL is strongly preferred: it is cacheable, it can carry an
 * `integrity` hash, and it keeps the form document small. `code` exists for
 * plugins that generate their UI per call and for local development.
 */
export interface RendererSpec {
  type: RendererType

  /**
   * URL of an ES module the guest imports.
   *
   * Made absolute by the host before it is handed over, because neither sandbox
   * has a base URL that a relative path can be resolved against. A plugin
   * serving its bundle from its own service should give an absolute URL; a
   * relative one is resolved against the host document, which is what a plugin
   * deployed alongside the host means by it.
   */
  module?: string

  /**
   * The guest module's source, inline. Loaded as a blob module inside the
   * sandbox. Carries the same contract as `module`: a default export, or a
   * named `mount`.
   */
  code?: string

  /**
   * Subresource-integrity hash (`sha256-` / `sha384-` / `sha512-`) of the
   * module's bytes. Verified by the host before the module is handed to the
   * sandbox; a mismatch is a hard failure, not a warning.
   *
   * The sandbox is a containment boundary, not an authenticity one — it stops a
   * malicious guest from reaching the host, but it cannot tell you the bytes
   * came from the plugin you trust. This is what does that, and a catalog
   * plugin should always ship it.
   */
  integrity?: string

  /** What the bundle was authored in. Informational — see {@link GuestFramework}. */
  framework?: GuestFramework

  /**
   * Narrows the host's element allow-list for this one form. Only meaningful as
   * a *reduction*: names outside the host's own policy are ignored rather than
   * granted, so a plugin can restrain itself but never widen its reach.
   */
  elements?: readonly string[]

  /**
   * How tall the sandbox is. `auto` lets the content decide, which the `remote`
   * renderer gets for free (the nodes are host nodes) and the `iframe` renderer
   * achieves by reporting its own scroll height back. A number is a fixed pixel
   * height.
   */
  height?: 'auto' | number

  /**
   * Milliseconds the guest has to call `ready()` before the host gives up and
   * shows the fallback. Guards against a guest that hangs on import, which would
   * otherwise leave an empty drawer forever. Defaults to 10000.
   */
  timeout?: number

  /**
   * Whether the host hands the settings profile to the guest. **Off by
   * default**, because a settings profile holds credentials and the guest is,
   * by construction, the party we are isolating. A guest that needs to reach
   * its own service does it through `ctx.call`, where the *host* attaches the
   * credentials and the guest never sees them.
   */
  exposeSettings?: boolean
}

/** `renderer` as it may appear on the wire: absent, a bare name, or the object. */
export type RendererField = RendererType | RendererSpec | undefined | null

/**
 * The form document, with the one new key.
 *
 * Structurally the SDK's `FormBuilder` plus `renderer`. The schema strings are
 * unchanged and still carry the data contract — a `remote` guest is handed the
 * parsed schema too, because "what shape is the value I must produce" is the
 * one thing every renderer needs regardless of how it draws.
 */
export interface FormDocument {
  jsonschema?: string | Record<string, unknown>
  jsonui?: string | Record<string, unknown>
  schema?: string | Record<string, unknown>
  uischema?: string | Record<string, unknown>
  submit_to?: string
  submitTo?: string
  renderer?: RendererField
}

const RENDERER_TYPES = new Set<string>(['jsonforms', 'remote', 'iframe'])

/** The default every absent, malformed or unrecognised `renderer` resolves to. */
export const DEFAULT_RENDERER: RendererSpec = { type: 'jsonforms' }

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value)
}

/**
 * `renderer` as it arrived → the spec the host acts on.
 *
 * Total, and biased towards the safe answer: anything this function cannot make
 * sense of becomes `jsonforms`. There is no shape of input for which it throws,
 * because it runs on a third party's document inside a drawer that must still
 * open — a plugin's malformed `renderer` is its bug, and it degrades to the
 * declarative form it also shipped.
 *
 * A code renderer naming neither `module` nor `code` likewise degrades: asking
 * for a sandbox and then not saying what to run in it is not a request the host
 * can honour, and an empty sandbox is worse than a form.
 */
export function resolveRenderer(field: RendererField): RendererSpec {
  if (typeof field === 'string') {
    return RENDERER_TYPES.has(field) ? { type: field as RendererType } : DEFAULT_RENDERER
  }

  if (!isPlainObject(field)) return DEFAULT_RENDERER

  const type = typeof field.type === 'string' && RENDERER_TYPES.has(field.type)
    ? (field.type as RendererType)
    : 'jsonforms'

  if (type === 'jsonforms') return DEFAULT_RENDERER

  const module = typeof field.module === 'string' && field.module.trim() ? field.module.trim() : undefined
  const code = typeof field.code === 'string' && field.code.trim() ? field.code : undefined
  if (!module && !code) return DEFAULT_RENDERER

  const elements = Array.isArray(field.elements)
    ? field.elements.filter((name): name is string => typeof name === 'string')
    : undefined

  const height = field.height === 'auto' || (
    typeof field.height === 'number' && Number.isFinite(field.height) && field.height >= 0
  ) ? field.height as 'auto' | number : 'auto'

  const timeout = typeof field.timeout === 'number' && Number.isFinite(field.timeout) && field.timeout > 0
    ? field.timeout
    : 10_000

  return {
    type,
    module,
    code,
    integrity: typeof field.integrity === 'string' ? field.integrity : undefined,
    framework: typeof field.framework === 'string' ? field.framework : undefined,
    elements: elements?.length ? elements : undefined,
    height,
    timeout,
    exposeSettings: field.exposeSettings === true,
  }
}

/** Whether this spec needs a sandbox — i.e. whether the plugin shipped code. */
export function isSandboxed(spec: RendererSpec): boolean {
  return spec.type === 'remote' || spec.type === 'iframe'
}
